import type { SingleTextEdit } from "../../../../common/core/textEdit.js";
import type { Command } from "../../../../common/languages.js";
import type { InlineCompletionItem } from "./provideInlineCompletions.js";

export class InlineEdit {
	constructor(
		public readonly edit: SingleTextEdit,
		public readonly commands: readonly Command[],
		public readonly inlineCompletion: InlineCompletionItem,
	) {}

	public get range() {
		return this.edit.range;
	}

	public get text() {
		return this.edit.text;
	}

	public equals(other: InlineEdit): boolean {
		return (
			this.edit.equals(other.edit) &&
			this.inlineCompletion === other.inlineCompletion
		);
	}
}
